CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, date TEXT, time TEXT, kind TEXT DEFAULT 'exam');
CREATE TABLE IF NOT EXISTS topics(id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL, title TEXT NOT NULL, done INTEGER DEFAULT 0, mins INTEGER DEFAULT 45, diff TEXT DEFAULT 'medium');
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, title TEXT NOT NULL, kind TEXT DEFAULT 'todo', due TEXT, done INTEGER DEFAULT 0, area_id INTEGER, est INTEGER, diff TEXT DEFAULT 'medium', done_at TEXT);
CREATE TABLE IF NOT EXISTS quizzes(id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL, title TEXT NOT NULL, date TEXT, done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS qt(id INTEGER PRIMARY KEY AUTOINCREMENT, quiz_id INTEGER NOT NULL, topic_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS dump(id INTEGER PRIMARY KEY AUTOINCREMENT, text TEXT NOT NULL, done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS rem(id INTEGER PRIMARY KEY AUTOINCREMENT, text TEXT NOT NULL, at TEXT, done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS habits(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hlog(id INTEGER PRIMARY KEY AUTOINCREMENT, habit_id INTEGER NOT NULL, day TEXT NOT NULL, UNIQUE(habit_id, day));
CREATE TABLE IF NOT EXISTS log(id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, kind TEXT, text TEXT, mins INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS areas(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, color TEXT, sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS goals(id INTEGER PRIMARY KEY AUTOINCREMENT, area_id INTEGER, title TEXT NOT NULL, why TEXT, done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS steps(id INTEGER PRIMARY KEY AUTOINCREMENT, goal_id INTEGER NOT NULL, title TEXT NOT NULL, done INTEGER DEFAULT 0, sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS today(id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, ref_kind TEXT, ref_id INTEGER, title TEXT NOT NULL, sort INTEGER DEFAULT 0, done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS routines(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, part TEXT DEFAULT 'am');
CREATE TABLE IF NOT EXISTS rsteps(id INTEGER PRIMARY KEY AUTOINCREMENT, routine_id INTEGER NOT NULL, title TEXT NOT NULL, sort INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS rlog(id INTEGER PRIMARY KEY AUTOINCREMENT, rstep_id INTEGER NOT NULL, day TEXT NOT NULL, UNIQUE(rstep_id, day));
CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY AUTOINCREMENT, area_id INTEGER, text TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rounds(id INTEGER PRIMARY KEY AUTOINCREMENT, topic_id INTEGER NOT NULL, done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS days(id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL UNIQUE, start TEXT DEFAULT '07:00', end TEXT DEFAULT '23:00');
CREATE TABLE IF NOT EXISTS blocks(id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, start TEXT NOT NULL, mins INTEGER DEFAULT 45, kind TEXT DEFAULT 'fixed', title TEXT, ref_kind TEXT, ref_id INTEGER, done INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS timer(id INTEGER PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, start_at INTEGER, start TEXT, plan_mins INTEGER DEFAULT 0, act_mins INTEGER DEFAULT 0, pauses INTEGER DEFAULT 0, end_kind TEXT DEFAULT 'open', rating INTEGER, ref_kind TEXT, ref_id INTEGER, diff TEXT);
CREATE TABLE IF NOT EXISTS prefs(id INTEGER PRIMARY KEY AUTOINCREMENT, k TEXT NOT NULL UNIQUE, v TEXT);
